# Simplified presentation 1: slide text, visualisation, notes (facts unchanged)
P1 = {
1: dict(text=['Заголовок: «Дизайн-мышление в организации: внедрение и культура»','Подзаголовок: «Курс „Дизайн-мышление“, неделя 11»','Служебная строка: «Almaty Management University»'],
 viz='только текст; титульный слайд задаёт стиль презентации.',
 notes='Тема доклада — как дизайн-мышление приживается в компании. На прошлых занятиях мы проходили сам процесс: эмпатия, идеи, прототип, тест. Но если одна команда прошла этот процесс, это ещё не значит, что так работает вся компания. Сегодня разберём, что для этого нужно, на примерах четырёх компаний, а в конце я предложу задание.'),
2: dict(text=['Заголовок: «Инструмент есть — подготовки нет»','Цитата: «Дизайн-мышление напоминает фантастический гоночный велосипед <…> Но его наличие не означает, что мы сможем пересечь Альпы. Нужна еще и соответствующая физическая подготовка!»','Подпись: «Леврик и др., 2020, с. 190»'],
 viz='крупная цитата; метафора задаёт рамку всей лекции.',
 notes='Леврик, Линк и Лейфер сравнивают дизайн-мышление с гоночным велосипедом. На нём можно уехать далеко, но через Альпы он сам не перевезёт: нужна физическая подготовка. В компании такая подготовка — это то, как она устроена: кто принимает решения и как отделы работают вместе. Об этом и пойдёт речь.'),
3: dict(text=['Заголовок: «Отделы работают каждый на себя»','Схема: «производство», «маркетинг», «группа продуктов» → разорванная линия → «клиент»','Подпись к схеме: «у каждого отдела свои цели; общие цели — только финансовые»','Цитата: «Эффективность дизайн-мышления прямо пропорциональна умению организации всесторонне и равномерно внедрять результат»','Подпись: «Леврик и др., 2020, с. 190–191»'],
 viz='три изолированных блока-отдела с горизонтальными подписями и клиент, к которому не доходит сквозная линия; схема читается за секунду.',
 notes='Первое препятствие — деление компании на отделы. У каждого отдела свои задачи и свои показатели, а общая цель часто выражена только в деньгах. Каждый улучшает свой участок, и никто не отвечает за опыт клиента целиком. Авторы делают вывод, который я приведу дословно: эффективность дизайн-мышления прямо пропорциональна умению организации всесторонне и равномерно внедрять результат. Иначе говоря, хорошая идея ничего не даёт, если компания не может довести её до клиента через все отделы.'),
4: dict(text=['Заголовок: «Три стадии компании»','«Семья» — всё держится на лидере','«Машина» — отделы и правила','«Организм» — части работают как целое','Вывод: «Дизайн-мышление лучше всего работает на третьей стадии»','Подпись: «Леврик и др., 2020, с. 192»'],
 viz='три слова-стадии слева направо со стрелками; третья стадия выделена как цель.',
 notes='Те же авторы описывают три стадии жизни компании. Сначала она похожа на семью: всё держится на основателе. Потом растёт и становится машиной: появляются отделы, правила, ставка на эффективность. Третья стадия — организм, где части работают как единое целое. По опыту авторов, дизайн-мышление лучше всего работает именно на третьей стадии. Поэтому компанию время от времени нужно перестраивать; авторы сравнивают это с обрезкой яблони, после которой она снова даёт урожай.'),
5: dict(text=['Заголовок: «Социальная технология»','Формула: «инструменты + понимание людей»','Аналогия: «TQM → производство», «дизайн-мышление → инновации»','Что даёт хороший процесс: лучшие решения; меньше риска при изменениях; поддержку сотрудников','Подпись: «Liedtka, 2018: 50 проектов за семь лет»'],
 viz='крупная формула вверху, под ней две строки аналогии и три результата в ряд.',
 notes='Жанна Лидтка изучила 50 проектов за семь лет и предложила смотреть на дизайн-мышление как на социальную технологию: это набор инструментов плюс понимание того, как работают люди. Её аналогия — система управления качеством TQM, которая в 1980-е изменила производство. По Лидтке, дизайн-мышление может сделать то же для инноваций. Хороший процесс, по её словам, даёт три результата: лучшие решения, меньшие риски и издержки изменений и поддержку сотрудников. Ещё одно её наблюдение: чёткая структура процесса помогает людям не попадать в типичные ловушки мышления — излишний оптимизм, поиск только подтверждающих фактов, привязанность к первому решению.'),
6: dict(text=['Заголовок: «Как думают менеджеры роста»','Было → Стало:','«Не задавай вопрос, ответа на который не знаешь» → «Начинай с неизвестного»','«Мысли масштабно» → «Фокусируйся на реальных потребностях людей»','«Если идея хороша, деньги найдутся» → «Давай стартовое финансирование нужным людям и задачам»','«Семь раз отмерь — один раз отрежь» → «Делай маленькие ставки быстро»','Подпись: «Liedtka & Ogilvie, 2011: 50 менеджеров»'],
 viz='таблица «было → стало»; старые правила приглушены, новые выделены.',
 notes='Лидтка и Огилви изучили 50 менеджеров, которые смогли вырастить бизнес в зрелых компаниях. Эти люди действуют иначе, чем учат привычные управленческие правила. Слева привычные правила, справа те, которыми пользовались эти менеджеры. Например, вместо «семь раз отмерь» — «делай маленькие ставки быстро»: пробовать недорого и сразу учиться на результате. Анализ при этом никто не отменяет: по выводу авторов, нужны оба набора инструментов — дизайнерский для нового и аналитический для стабильного бизнеса.'),
7: dict(text=['Заголовок: «Матрица путей роста»','Оси: «Клиенты: прежние → новые» × «Продукт: прежний → новый»','Постепенные — обновление продукта','Эволюционные — Toyota Prius; Tata Nano','Революционные — Sony Walkman, Apple iPod','Отдельно: «Провал: Segway» и цитата «изобретение — это еще не инновация»','Подпись: «Браун, 2012, гл. 7»'],
 viz='матрица 2×2 с понятными подписями осей и одним примером в каждой зоне; Segway — отдельной врезкой справа.',
 notes='Матрица путей роста от IDEO помогает понять, во что вкладывается компания. По одной оси — делаем ли мы новый продукт или улучшаем прежний, по другой — для прежних клиентов или для новых. Постепенные инновации — обновление того, что уже есть; так работает большинство компаний. Эволюционные — шаг в новое: Toyota Prius ответил на новую потребность прежних клиентов, Tata Nano адаптировал идею микроавтомобиля для новых покупателей по запланированной цене 2000 долларов. Революционные создают новый рынок, как Walkman или iPod, но случаются редко. Отдельно — Segway за 4000 долларов: по Брауну, он провалился, потому что никто глубоко не изучил, как люди впишут его в свою жизнь. Формула Брауна: изобретение — это ещё не инновация. Его совет — держать проекты во всех зонах матрицы.'),
8: dict(text=['Заголовок: «Kaiser Permanente: обучили своих»','Было: «≈45 мин» — совещание в сестринской перед сменой, информация терялась','Решение: передача смены у постели пациента; прототип за неделю','Стало: время до первого контакта с пациентом сократилось «более чем вдвое»','Позже (с 2011 г.): модель NKEplus — 125 отделений, 14 больниц','Подпись: «Браун, 2012, гл. 7; Brown, 2008; PMID 26108123»'],
 viz='сравнение «было → стало» двумя крупными блоками; масштабирование — строкой ниже.',
 notes='Первый пример — медицинская компания Kaiser Permanente. В 2003 году она решила не нанимать много дизайнеров, а обучить дизайн-мышлению собственных медсестёр, врачей и администраторов. Один из проектов касался пересменки в четырёх больницах. Оказалось, что медсёстры тратили около 45 минут в начале смены на совещание в сестринской, и важная информация о пациентах терялась. Команда предложила передавать смену прямо у постели пациента; первый прототип сделали за неделю. В результате время до первого контакта с пациентом сократилось более чем вдвое. Позже, с 2011 года, модель NKEplus внедряли в 125 отделениях 14 больниц, и оценка общения медсестёр по опросу пациентов HCAHPS выросла с 73,1 до 76,4 процента; разница статистически значима. Прямой связи этой программы с пилотом 2003 года мои источники не описывают.'),
9: dict(text=['Заголовок: «P&G: дизайн в ДНК компании»','Решения руководителя (A. G. Lafley): назначил вице-президента по дизайну (К. Коцка); встроил дизайнеров в бизнес-подразделения; создал Innovation Gym; поднял инновации и дизайн до уровня базовой стратегии','Акцент: «≈100 внутренних фасилитаторов (2008)»; «более 40 воркшопов за год»','Подписи: «Браун, 2012, гл. 7; IMD; Rae, 2008»'],
 viz='список решений слева, стрелка к крупному числу «≈100» справа.',
 notes='Второй пример — Procter & Gamble. Браун пишет прямо: все семинары в мире не изменили бы P&G без решений генерального директора Алана Лафли. Он назначил Клаудию Коцку вице-президентом по дизайну, встроил дизайнеров в подразделения, создал инновационный центр Innovation Gym и поднял инновации и дизайн до уровня стратегии. К 2008 году в компании работало около ста собственных фасилитаторов, то есть людей, которые ведут сессии дизайн-мышления, и за год они провели больше сорока воркшопов. В этом кейсе решение принимал первый руководитель, а компания вырастила собственных специалистов.'),
10: dict(text=['Заголовок: «Steelcase: от мебели к среде»','Workplace Futures — исследовательская группа; Nurture — подразделение для больниц','Было: «разработка комфортных кресел для приемного покоя»','Стало: «Как можно создать зоны приватности на общественных площадях?»','Подпись: «Браун, 2012, гл. 7»'],
 viz='сравнение «было → стало» для формулировки задачи; старая формулировка зачёркнута.',
 notes='Третий пример — производитель мебели Steelcase. Компания создала свою исследовательскую группу Workplace Futures, а по её прогнозам — подразделение Nurture, которое проектирует пространство для больниц. Посмотрите, как изменилась сама задача. Раньше она звучала как «разработка комфортных кресел для приёмного покоя». Теперь — «как можно создать зоны приватности на общественных площадях?». Компания думает уже не о мебели, а о том, как человек чувствует себя в пространстве. Вместе с клиникой Mayo Steelcase проверяла решения в контролируемом эксперименте и опубликовала оба результата.'),
11: dict(text=['Заголовок: «Nokia Ovi: оценка в книге и что было дальше»','29.08.2007 — объявлен Ovi','2009 — Браун приводит Ovi как успешное подразделение','16.05.2011 — Nokia объявляет об отказе от бренда Ovi','2014 — Microsoft покупает подразделение устройств и сервисов Nokia','Вывод: «Успех на момент описания ещё не означает успешного внедрения»','Подписи: «Браун, 2012, гл. 7; Ovi (Nokia), б. г.; Zeman, 2011»'],
 viz='таймлайн из четырёх точек; точка 2009 года выделена.',
 notes='Четвёртый пример — с неоднозначным итогом. С 2006 года исследователи и дизайнеры Nokia изучали, как люди общаются и делятся информацией, и компания запустила сервис Ovi; о нём объявили 29 августа 2007 года. В книге 2009 года Браун приводит Ovi как успех. Но 16 мая 2011 года Nokia объявила об отказе от бренда Ovi, к концу 2012 года переход завершился, а в 2014 году подразделение устройств и сервисов Nokia купила Microsoft. Почему так произошло, в моих источниках не разбирается, поэтому причины я называть не буду. Вывод для анализа: успех проекта в момент, когда о нём пишут, ещё не означает успешного внедрения. Проверяйте, что стало с компанией через несколько лет.'),
12: dict(text=['Заголовок: «Цифры и их ограничения»','«301%» — ROI практики дизайн-мышления IBM за 3 года — «заказано IBM»','«+32 п. п.» — рост выручки у верхнего квартиля McKinsey Design Index; TRS: +56 п. п. — «корреляция, а не причинность»','Подпись: «Forrester Consulting, 2018; McKinsey & Company, 2018»'],
 viz='две крупные цифры, под каждой — ограничение.',
 notes='Часто спрашивают, окупается ли это. Есть две известные цифры. Отчёт Forrester 2018 года: выгоды IBM от практики дизайн-мышления за три года — 48,4 млн долларов при затратах около 12 млн, ROI — 301%. Но исследование заказала сама IBM. McKinsey в 2018 году пять лет наблюдала за 300 компаниями: у лучшей четверти по дизайну выручка росла на 32 процентных пункта быстрее, чем у отраслевых конкурентов, а доходность акционеров — на 56 процентных пунктов. У остальных трёх четвертей разница была незначительной. И это корреляция, а не причинность: исследование не доказывает, что рост дал именно дизайн. Такие цифры можно приводить, но вместе с их ограничениями.'),
13: dict(text=['Заголовок: «Почему не получается»','Идеи с воркшопов редко доходят до реализации (Ackermann, 2023)','Внешние консультанты не знают контекста проблемы (Ackermann, 2023)','Отдельные семинары без организационных изменений имеют ограниченное влияние (Браун, 2012, гл. 7)'],
 viz='три причины крупным текстом, источник каждой справа.',
 notes='Почему внедрение часто не удаётся? Ребекка Акерманн в статье в MIT Technology Review в 2023 году писала, что идеи с воркшопов организации редко доводят до реализации, а внешние консультанты часто не знают реального контекста: в одном из её примеров работник школы усомнился в идеях консультантов, которые ни с кем в школе не поговорили. Браун ещё в книге 2009 года предупреждал о том же: отдельные семинары без изменений в организации дают ограниченный эффект. Критик метода и его сторонник указывают на одну проблему: она возникает на этапе внедрения.'),
14: dict(text=['Заголовок: «Что нужно для внедрения»','Люди: лидеры; междисциплинарные команды; сеть сторонников во всех отделах','Процесс: семинары; пилотные проекты; измерение эффекта','Условия: выделенное пространство; стимулы для сотрудничества подразделений','Под элементами — пример из кейсов (Kaiser, P&G, Steelcase)','Подпись: «Браун, 2012, гл. 7; Леврик и др., 2020, с. 193»'],
 viz='три колонки «Люди / Процесс / Условия» (группировка докладчика) вместо радиальной схемы; восемь элементов читаются как чек-лист.',
 notes='Соберём всё вместе. Условия внедрения удобно разделить на три группы. Люди: лидеры, которые разрешают учиться и экспериментировать, междисциплинарные команды и сеть сторонников во всех отделах — по Леврику, инициатива одного отдела долго не живёт. Процесс: семинары, чтобы понять подход, пилотные проекты, чтобы показать пользу, и измерение результата. Условия: отдельное пространство, как Innovation Gym в P&G, и стимулы, чтобы подразделения сотрудничали. Браун отмечает, что эти элементы работают, только когда действуют согласованно.'),
15: dict(text=['Заголовок: «Задание: разберите кейс внедрения»','Выберите компанию, успешно или неуспешно внедрившую дизайн-мышление','1. Кто начал внедрение? Какую роль играло руководство?','2. Как устроены команды? Есть ли сеть сторонников?','3. Какой эффект измерен и кем? Есть ли независимые данные?','4. Что стало с инициативой через несколько лет?'],
 viz='четыре крупных нумерованных вопроса; справа — подсказка, какой кейс лекции помогает ответить.',
 notes='Задание на неделю: выберите компанию, которая внедряла дизайн-мышление успешно или неуспешно, и разберите её по четырём вопросам на слайде. Кто начал внедрение и какую роль играло руководство — как в P&G. Как устроены команды — как в Kaiser. Какой результат измерен и кем — вспомните ограничения цифр IBM и McKinsey. И что стало с компанией через несколько лет — как с Nokia. Делайте выводы по фактам и указывайте, откуда они.'),
}
